clip "Window" {
  fill #27486d
  rect 20 20 200 140
  stroke off
  circle 120 90 60
}

pencil 4B
repeat 12 as i {
  line (20 + i * 6) 20 (40 + i * 6) 140
}
smear 24 0.6 10 80, 150 80

define "tick" {
  line 0 10 4 14
  line 4 14 14 0
}
place "tick" at 40 40 scale 2

